package day7;

public class partice1ascendingorder {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
int a[]= {50,30,10,20,80};
for (int i = 0; i < a.length; i++) {
    for (int j = i + 1; j < a.length; j++) {
        if (a[i] > a[j]) {
            int temp = a[i];
            a[i] = a[j];
            a[j] = temp;
        }
    } 
}

for (int i = 0; i < a.length; i++) {
    System.out.print(a[i] + " ");
}

	}

}
